create extension if not exists pgcrypto;
create table if not exists public.leads(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),nome text,whatsapp text unique,instagram text,dor text,faturamento text,motivo text,status_funil text not null default 'parcial' check(status_funil in('parcial','completo','enviou_whatsapp')),status_comercial text not null default 'novo' check(status_comercial in('novo','contatado','qualificado','call agendada','fechado','descartado')),notas text not null default '',utm_source text,utm_medium text,utm_campaign text,utm_content text,utm_term text,referrer text,user_agent text,session_id text,consentimento boolean not null default false,consentimento_em timestamptz);
create table if not exists public.funnel_events(id uuid primary key default gen_random_uuid(),lead_id uuid null references public.leads(id) on delete set null,session_id text not null,step int not null check(step between 0 and 7),event text not null,created_at timestamptz not null default now());
create index if not exists leads_whatsapp_idx on public.leads(whatsapp);create index if not exists leads_created_at_idx on public.leads(created_at desc);create index if not exists leads_status_funil_idx on public.leads(status_funil);create index if not exists funnel_events_session_idx on public.funnel_events(session_id);create index if not exists funnel_events_step_idx on public.funnel_events(step);
alter table public.leads enable row level security;alter table public.funnel_events enable row level security;

